from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # Extract inputs
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        # Parse the hint
        parts = current_hint.split()
        op = parts[0]  # 'sum', 'product', or 'difference'
        # The rest describes the condition
        cond = ' '.join(parts[1:])

        # Build a function that checks the condition on an integer value
        def make_checker(cond_str):
            if cond_str.startswith('is less than'):
                v = int(cond_str.split()[-1])
                return lambda x: x < v
            if cond_str.startswith('is greater than'):
                v = int(cond_str.split()[-1])
                return lambda x: x > v
            if cond_str.startswith('contains digit'):
                v = cond_str.split()[-1]
                return lambda x: v in str(x)
            if cond_str == 'is even':
                return lambda x: x % 2 == 0
            if cond_str == 'is odd':
                return lambda x: x % 2 == 1
            if cond_str.startswith('is between'):
                nums = [int(s.strip(',')) for s in cond_str.split() if s.isdigit()]
                v1, v2 = nums[0], nums[1]
                return lambda x: v1 <= x <= v2
            # default reject
            return lambda x: False

        checker = make_checker(cond)

        n = len(current_grid)
        valid_moves = []
        for i in range(n):
            for j in range(n):
                if current_grid[i][j] != 0:
                    continue
                # compute value according to op
                if op == 'sum':
                    val = (i+1) + (j+1)
                elif op == 'product':
                    val = (i+1) * (j+1)
                elif op == 'difference':
                    val = abs((i+1) - (j+1))
                else:
                    continue
                if checker(val):
                    valid_moves.append((i+1, j+1))

        # Choose move
        if valid_moves:
            position_selected = valid_moves[0]
        else:
            # no valid hint-based moves: pick first empty
            position_selected = None
            for i in range(n):
                for j in range(n):
                    if current_grid[i][j] == 0:
                        position_selected = (i+1, j+1)
                        break
                if position_selected:
                    break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

