from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # current_grid is a list of lists of integers
        current_grid = message.message[0].data[0]
        # current_hint is a string
        current_hint = message.message[0].data[1]
        # player_idx is an integer: 1 or 2
        player_idx = message.message[0].data[2]

        # parse operation
        hint = current_hint.lower()
        if hint.startswith('sum'):
            op = lambda r, c: r + c
        elif hint.startswith('product'):
            op = lambda r, c: r * c
        elif hint.startswith('difference'):
            op = lambda r, c: abs(r - c)
        else:
            # default: sum
            op = lambda r, c: r + c

        # parse condition
        def make_pred(h: str):
            if 'is less than' in h:
                v = int(h.split('is less than')[1].strip())
                return lambda x: x < v
            if 'is greater than' in h:
                v = int(h.split('is greater than')[1].strip())
                return lambda x: x > v
            if 'contains digit' in h:
                v = h.split('contains digit')[1].strip()
                return lambda x: v in str(x)
            if 'is between' in h:
                parts = h.split('is between')[1].strip().split('and')
                v1 = int(parts[0].strip())
                v2 = int(parts[1].split(',')[0].strip())
                return lambda x: v1 <= x <= v2
            if 'is even' in h:
                return lambda x: x % 2 == 0
            if 'is odd' in h:
                return lambda x: x % 2 == 1
            # fallback always true
            return lambda x: True

        predicate = make_pred(hint)

        n_rows = len(current_grid)
        n_cols = len(current_grid[0]) if n_rows > 0 else 0
        position_selected = None
        # search for first valid move
        for i in range(1, n_rows+1):
            for j in range(1, n_cols+1):
                if current_grid[i-1][j-1] != 0:
                    continue
                val = op(i, j)
                if predicate(val):
                    position_selected = (i, j)
                    break
            if position_selected:
                break
        # fallback: first empty
        if position_selected is None:
            for i in range(1, n_rows+1):
                for j in range(1, n_cols+1):
                    if current_grid[i-1][j-1] == 0:
                        position_selected = (i, j)
                        break
                if position_selected:
                    break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

