        elif hint.startswith('product'):
            op = lambda r, c: r * c
        elif hint.startswith('difference'):
            op = lambda r, c: abs(r - c)
        else:
            # default: sum
            op = lambda r, c: r + c

        # parse condition
        def make_pred(h: str):
            if 'is less than' in h:
                v = int(h.split('is less than')[1].strip())
                return lambda x: x < v
            if 'is greater than' in h:
                v = int(h.split('is greater than')[1].strip())
                return lambda x: x > v
            if 'contains digit' in h:
