                return lambda x: v in str(x)
            if 'is between' in h:
                parts = h.split('is between')[1].strip().split('and')
                v1 = int(parts[0].strip())
                v2 = int(parts[1].split(',')[0].strip())
                return lambda x: v1 <= x <= v2
            if 'is even' in h:
                return lambda x: x % 2 == 0
            if 'is odd' in h:
