        # operations: sum, product, difference
        # conditions: is less than v1, is greater than v1, contains digit v1,
        # is even, is odd, is between v1 and v2, inclusive
        op_match = re.match(r"(sum|product|difference)", current_hint)
        cond = current_hint[len(op_match.group(1)):].strip() if op_match else ""
        op = op_match.group(1) if op_match else "sum"

        def metric(r, c):
            if op == 'sum': return r + c
            if op == 'product': return r * c
            # difference means absolute difference
            return abs(r - c)

        # parse condition
        c_less = re.match(r"is less than (\d+)", cond)
        c_greater = re.match(r"is greater than (\d+)", cond)
