        c_odd = 'is odd' in cond

        def check(val):
            if c_less:
                return val < int(c_less.group(1))
            if c_greater:
                return val > int(c_greater.group(1))
            if c_between:
                lo = int(c_between.group(1)); hi = int(c_between.group(2))
                return lo <= val <= hi
            if c_contains:
                return c_contains.group(1) in str(val)
            if c_even:
                return val % 2 == 0
            if c_odd:
                return val % 2 == 1
            return False

        # gather all valid empty cells
        candidates = []  # list of (r,c)
        for i in range(n):
            for j in range(n):
                if current_grid[i][j] != 0:
                    continue
                v = metric(i+1, j+1)  # grid is 1-indexed
                if check(v):
                    candidates.append((i, j))

        # if no candidates, pass (shouldn't happen), pick first empty
        if not candidates:
            for i in range(n):
                for j in range(n):
                    if current_grid[i][j] == 0:
                        position_selected = (i+1, j+1)
                        break
                else:
                    continue
                break
