        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # Unpack inputs
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]
        n = len(current_grid)

        # Parse hint: operation and condition
        operation = current_hint.split()[0]
        nums = list(map(int, re.findall(r'-?\d+', current_hint)))
        cond = None
        if 'is less than' in current_hint:
            v = nums[0]
            cond = lambda val: val < v
        elif 'is greater than' in current_hint:
            v = nums[0]
            cond = lambda val: val > v
        elif 'contains digit' in current_hint:
            d = str(nums[0])
            cond = lambda val: d in str(val)
        elif 'is even' in current_hint:
            cond = lambda val: val % 2 == 0
        elif 'is odd' in current_hint:
            cond = lambda val: val % 2 == 1
        elif 'is between' in current_hint:
            v1, v2 = nums[0], nums[1]
            cond = lambda val: v1 <= val <= v2
        else:
            # fallback allow all
            cond = lambda val: True

        # Helper to compute operation value
        def compute_val(r, c):
            if operation == 'sum':
                return r + c
            if operation == 'product':
                return r * c
            # treat difference as absolute
            return abs(r - c)

        # Collect valid moves
        candidates = []
        for i in range(n):
            for j in range(n):
                if current_grid[i][j] != 0:
                    continue
                r, c = i+1, j+1
                val = compute_val(r, c)
                if cond(val):
                    candidates.append((r, c))

        # If no valid moves, pick first empty
        if not candidates:
            for i in range(n):
                for j in range(n):
                    if current_grid[i][j] == 0:
                        position_selected = (i+1, j+1)
                        break
                else:
                    continue
                break
        else:
            # Score candidates: neighbors + closeness
            best = None
            best_score = None
            for (r, c) in candidates:
                # count our adjacent stones
                neigh = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        rr, cc = r-1+dr, c-1+dc
                        if 0 <= rr < n and 0 <= cc < n and current_grid[rr][cc] == player_idx:
                            neigh += 1
                # distance to goal side
                if player_idx == 1:
                    dist = n - c
                else:
                    dist = n - r
                score = neigh * 100 - dist
                if best is None or score > best_score:
                    best_score = score
                    best = (r, c)
            position_selected = best

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

